package com.projectdark.mobile;
import static org.junit.Assert.*;
import android.content.*;import android.graphics.*;import com.projectdark.mobile.world.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class NpcTravelV248Test {
 MineTownV203Test f;Context c;
 @Before public void setup(){f=new MineTownV203Test();f.reset();c=RuntimeEnvironment.getApplication();}
 void manager(GameView v,String id)throws Exception{RuntimeState s=f.field(v,"state");WorldRuntimeAdapter w=(WorldRuntimeAdapter)f.call(v,"activeWorld",new Class<?>[]{});assertTrue(id,CampaignNavigationTest.walk(w,w.requestNpcApproach(id)));RuntimeState.Npc npc=s.npcs().stream().filter(n->n.id.equals(id)).findFirst().get();assertEquals(InteractionController.TickResult.DIALOG_OPENED,((InteractionController)f.field(v,"interaction")).request(s,npc));}
 void pick(GameView v,String dest)throws Exception{RuntimeState s=f.field(v,"state");RectF r=TownTravelWindow.cardFor(s.currentMapId(),dest);assertNotNull(dest,r);TownInteriorTest.tap(v,r.centerX(),r.centerY());}
 void shot(GameView v,String name)throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));PortalServicesV248Test.save(b,name);b.recycle();}
 @Test public void realNpcMenusChargeExactlyOnceAcrossEveryExistingTownPairAndColdRestart()throws Exception{
  GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=f.field(v,"state");List<TownTravel.Destination> towns=new ArrayList<>(TownTravel.TOWNS);towns.add(TownTravel.forMap(CampaignWorld.PIET));int routes=0;
  for(TownTravel.Destination from:towns)for(TownTravel.Destination to:TownTravel.TOWNS){if(from.map.equals(to.map)||!TownTravel.offers(from.map,to.map))continue;f.call(v,"travelTown",new Class<?>[]{String.class},from.map);s.rpg().restoreGold(1000);Map<String,Integer> inv=new LinkedHashMap<>(s.rpg().inventory());long xp=CampaignProgress.earnedExp(s.rpg());manager(v,from.npc);shot(v,"menu-"+from.map+"-"+to.map);RectF r=TownTravelWindow.cardFor(from.map,to.map);pick(v,to.map);assertEquals(from.map+" -> "+to.map,to.map,s.currentMapId());assertEquals(900,s.rpg().gold().longValue());assertEquals(inv,s.rpg().inventory());assertEquals(xp,CampaignProgress.earnedExp(s.rpg()));assertFalse(((InteractionController)f.field(v,"interaction")).dialogOpen());TownInteriorTest.tap(v,r.centerX(),r.centerY());assertEquals(900,s.rpg().gold().longValue());WorldMoveTargetController.TileCenter arrival=TownTravel.arrival(to.map);assertEquals(arrival.x,s.player().x,0);assertEquals(arrival.y,s.player().y,0);routes++;}
  assertEquals(21,routes);String last=s.currentMapId();v.pause();F5mSaveStore.install(c);GameView restored=new GameView(c);RuntimeState rs=f.field(restored,"state");assertEquals(last,rs.currentMapId());assertEquals(900,rs.rpg().gold().longValue());
 }
 @Test public void cancelPoorAndLockedCoastUseTheSamePaidMenuWithoutBypass()throws Exception{
  GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=f.field(v,"state");s.rpg().restoreGold(1000);manager(v,"pote_travel_guide");TownInteriorTest.tap(v,80,518);assertEquals(1000,s.rpg().gold().longValue());assertEquals(WorldDef.ID,s.currentMapId());manager(v,"pote_travel_guide");s.rpg().restoreGold(99);pick(v,AbelTownGeometry.ID);assertEquals(99,s.rpg().gold().longValue());assertEquals(WorldDef.ID,s.currentMapId());assertTrue(((InteractionController)f.field(v,"interaction")).dialogOpen());
  f.call(v,"travelTown",new Class<?>[]{String.class},AbelTownGeometry.ID);s.rpg().restoreGold(1000);manager(v,"abel_coast_departure");shot(v,"coast-backwonman-locked-menu");pick(v,AbelCoastGeometry.ENTRY);assertEquals(AbelTownGeometry.ID,s.currentMapId());assertEquals(1000,s.rpg().gold().longValue());
  v.setSkillTestMode(true);pick(v,AbelCoastGeometry.ENTRY);assertEquals(AbelCoastGeometry.ENTRY,s.currentMapId());assertEquals(900,s.rpg().gold().longValue());shot(v,"coast-paid-arrival");
 }
 @Test public void failedCommitOrMoveRestoresExactLiveActorsProgressAndGoldWithoutRespawn()throws Exception{
  RuntimeState s=new RuntimeState();s.enterCampaignMap("MAP_POTE_01",false);s.rpg().restoreGold(500);RuntimeState.Monster original=s.monsters().get(0);original.hp=17;String map=s.currentMapId(),progress=s.rpg().campaign().snapshot().toString();float x=s.player().x,y=s.player().y;
  assertEquals(NpcTravelTransaction.Result.SAVE_FAILED,NpcTravelTransaction.run(s,()->{s.enterCampaignMap(MineTownGeometry.ID,false);return true;},()->false));assertEquals(map,s.currentMapId());assertEquals(500,s.rpg().gold().longValue());assertSame(original,s.monsters().get(0));assertEquals(17,original.hp);assertEquals(x,s.player().x,0);assertEquals(y,s.player().y,0);assertEquals(progress,s.rpg().campaign().snapshot().toString());
  assertEquals(NpcTravelTransaction.Result.INVALID,NpcTravelTransaction.run(s,()->{s.enterCampaignMap(MineTownGeometry.ID,false);throw new IllegalStateException("simulated movement failure");},()->true));assertEquals(map,s.currentMapId());assertSame(original,s.monsters().get(0));assertEquals(500,s.rpg().gold().longValue());s.rpg().restoreGold(99);assertEquals(NpcTravelTransaction.Result.INSUFFICIENT_GOLD,NpcTravelTransaction.run(s,()->{fail("no transition");return true;},()->true));s.player().alive=false;assertEquals(NpcTravelTransaction.Result.INVALID,NpcTravelTransaction.run(s,()->true,()->true));
 }
}
